monsterPrograms.fodder:
# เศษมอน: ไล่งับมั่ว ๆ ใช้สกิลตราบใดที่ยังมีพลัง
def turn():
    if me.mp_pct > 30:
        cast("bite", random_of(enemies))
    else:
        attack(random_of(enemies))

